file.content:
-- Swarm dispatcher v0: Postgres 16. Единый источник истины.
-- Правила: любая запись воркера несёт lease_epoch (fencing); переход состояния и
-- событие в журнале пишутся в одной транзакции; время только через now() БД.
-- Коды ошибок: LS001 lease_lost, AR001 artifact_missing, CT001 contract_invalid,
-- GR000 task_not_found, GR001 cycle, GR002 depth, GR003 fanout, GR004 task_limit,
-- GR005 not_done, GR006 root_not_found, GR007 cross_root, GR008 not_pending,
-- GR009 not_blocked, RV001 review_stale, RV002 self_review, RV003 checks_failed,
-- WK001 worker_invalid, WK002 worker_unknown.

create table tasks (
  id           uuid primary key,
  root_id      uuid not null references tasks(id) deferrable initially deferred,
  state        text not null default 'pending'
               check (state in ('pending','ready','leased','review','done','blocked')),
  contract     jsonb not null,
  lease_epoch  bigint not null default 0,
  lease_owner  text,
  lease_until  timestamptz,
  attempts     int not null default 0,          -- сбои воркера (истекшие аренды)
  rework       int not null default 0,          -- циклы после ревью
  budget_cap   bigint not null check (budget_cap > 0),
  spent_tokens bigint not null default 0,
  result_ref   text,
  priority     int not null default 0,
  block_reason text,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now(),
  -- инвариант аренды: leased <=> есть владелец и срок
  check ((state = 'leased') = (lease_owner is not null and lease_until is not null))
);
create index tasks_claim_idx  on tasks (priority desc, created_at) where state = 'ready';
create index tasks_root_idx   on tasks (root_id);
create index tasks_lease_idx  on tasks (lease_until) where state = 'leased';
create index tasks_pending_idx on tasks (id) where state = 'pending';

create table artifacts (
  task_id      uuid not null references tasks(id),
  ref          text not null,                   -- 'sha256:...'
  created_by   text not null,
  lease_epoch  bigint not null,                 -- fencing-токен создателя
  content_type text,
  size_bytes   bigint,
  storage_path text not null,
  created_at   timestamptz not null default now(),
  primary key (task_id, ref)
);
alter table tasks add foreign key (id, result_ref) references artifacts (task_id, ref);

create table task_deps (
  task_id uuid not null references tasks(id) on delete cascade,
  dep_id  uuid not null references tasks(id) on delete cascade,
  primary key (task_id, dep_id),
  check (task_id <> dep_id)
);
create index task_deps_dep_idx on task_deps (dep_id);

create table workers (
  id            text primary key,
  capabilities  jsonb not null,                 -- {"ram_gb":16,"models":{"coder_class":2}}
  affinity_tags text[] not null default '{}',
  last_seen     timestamptz not null default now()
);
create index workers_seen_idx on workers (last_seen);

create table events (
  seq       bigserial primary key,
  task_id   uuid not null references tasks(id) on delete cascade,
  event_id  text not null,
  kind      text not null check (kind in ('created','dep_added','promoted','claimed',
            'artifact_saved','completed','review_submitted','reclaimed','reopened',
            'cascade_blocked','unblocked')),
  actor     text,
  payload   jsonb not null default '{}',
  at        timestamptz not null,
  prev_hash bytea,
  hash      bytea not null,
  unique (task_id, event_id)
);
create index events_task_idx on events (task_id, seq);

create table reviews (
  id           bigserial primary key,
  task_id      uuid not null,
  artifact_ref text not null,
  reviewer     text not null,
  verdict      text not null check (verdict in ('approved','changes_requested','rejected')),
  checks       jsonb not null,                  -- [{type,status,exit_code,log_ref,duration_ms}]
  created_at   timestamptz not null default now(),
  foreign key (task_id, artifact_ref) references artifacts (task_id, ref)
);

-- ---------- вспомогательные ----------
create function c_num(c jsonb, path text[], dflt numeric) returns numeric
language sql immutable as $$ select coalesce((c #>> path)::numeric, dflt) $$;

create function lock_root(p_root uuid) returns void
language sql as $$ select pg_advisory_xact_lock(hashtextextended(p_root::text, 0)) $$;

create function event_hash(p_prev bytea, p_task uuid, p_eid text, p_kind text,
                           p_actor text, p_payload jsonb, p_at timestamptz)
returns bytea language sql immutable as $$
  select sha256(coalesce(p_prev, '\x'::bytea) || convert_to(
    p_task::text || '|' || p_eid || '|' || p_kind || '|' || coalesce(p_actor, '') || '|' ||
    p_payload::text || '|' || to_char(p_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.US'),
    'UTF8')) $$;

-- Хэш-цепочка по задаче. Блокировка строки tasks сериализует запись, в том числе
-- первого события (у которого ещё нет строки events для блокировки).
create function append_event(p_task uuid, p_event_id text, p_kind text,
                             p_actor text, p_payload jsonb default '{}')
returns boolean language plpgsql as $$
declare v_prev bytea; v_at timestamptz := clock_timestamp();
begin
  perform 1 from tasks where id = p_task for update;
  if not found then raise exception 'task_not_found' using errcode = 'GR000'; end if;
  if exists (select 1 from events where task_id = p_task and event_id = p_event_id) then
    return false;                                   -- идемпотентность
  end if;
  select hash into v_prev from events where task_id = p_task order by seq desc limit 1;
  insert into events (task_id, event_id, kind, actor, payload, at, prev_hash, hash)
  values (p_task, p_event_id, p_kind, p_actor, p_payload, v_at, v_prev,
          event_hash(v_prev, p_task, p_event_id, p_kind, p_actor, p_payload, v_at));
  return true;
end $$;

create function verify_chain(p_task uuid) returns boolean language plpgsql stable as $$
declare e record; v_prev bytea := null;
begin
  for e in select * from events where task_id = p_task order by seq loop
    if e.prev_hash is distinct from v_prev then return false; end if;
    if e.hash <> event_hash(v_prev, e.task_id, e.event_id, e.kind, e.actor, e.payload, e.at) then
      return false;
    end if;
    v_prev := e.hash;
  end loop;
  return true;
end $$;

create function validate_contract(c jsonb) returns void language plpgsql immutable as $$
declare k text;
begin
  if jsonb_typeof(c->'checks') is distinct from 'array' or jsonb_array_length(c->'checks') = 0 then
    raise exception 'contract_invalid: checks required' using errcode = 'CT001';
  end if;
  foreach k in array array['min_ram_gb','coder_class'] loop
    if jsonb_exists(c->'needs', k) and jsonb_typeof(c->'needs'->k) <> 'number' then
      raise exception 'contract_invalid: needs.% must be number', k using errcode = 'CT001';
    end if;
  end loop;
  if jsonb_exists(c->'needs', 'affinity_tags') and jsonb_typeof(c->'needs'->'affinity_tags') <> 'array' then
    raise exception 'contract_invalid: needs.affinity_tags must be array' using errcode = 'CT001';
  end if;
  foreach k in array array['attempts','max_rework','max_depth','max_children','max_tasks'] loop
    if jsonb_exists(c->'budget', k) and jsonb_typeof(c->'budget'->k) <> 'number' then
      raise exception 'contract_invalid: budget.% must be number', k using errcode = 'CT001';
    end if;
  end loop;
end $$;

-- ---------- воркеры ----------
create function register_worker(p_id text, p_caps jsonb, p_tags text[] default '{}')
returns void language plpgsql as $$
begin
  if (p_caps ? 'ram_gb' and jsonb_typeof(p_caps->'ram_gb') <> 'number')
     or (p_caps #> '{models,coder_class}' is not null
         and jsonb_typeof(p_caps #> '{models,coder_class}') <> 'number') then
    raise exception 'worker_invalid' using errcode = 'WK001';
  end if;
  insert into workers (id, capabilities, affinity_tags, last_seen)
  values (p_id, p_caps, coalesce(p_tags, '{}'), now())
  on conflict (id) do update
    set capabilities = excluded.capabilities, affinity_tags = excluded.affinity_tags,
        last_seen = now();
end $$;

-- ---------- граф ----------
create function add_task(p_id uuid, p_root uuid, p_contract jsonb,
                         p_budget_cap bigint, p_priority int default 0)
returns void language plpgsql as $$
declare v_root uuid := coalesce(p_root, p_id); v_max numeric; v_cnt int;
begin
  perform validate_contract(p_contract);
  perform lock_root(v_root);
  if v_root <> p_id then
    select c_num(contract, '{budget,max_tasks}', 200) into v_max from tasks where id = v_root;
    if not found then raise exception 'root_not_found' using errcode = 'GR006'; end if;
    select count(*) into v_cnt from tasks where root_id = v_root;
    if v_cnt >= v_max then raise exception 'task_limit_exceeded' using errcode = 'GR004'; end if;
  end if;
  insert into tasks (id, root_id, contract, budget_cap, priority)
  values (p_id, v_root, p_contract, p_budget_cap, p_priority);
  perform append_event(p_id, 'created', 'created', 'planner', jsonb_build_object('root', v_root));
end $$;

create function add_dep(p_task uuid, p_dep uuid) returns void language plpgsql as $$
declare v_root uuid; v_root2 uuid; v_state text; v_maxd numeric; v_maxc numeric; v_len int;
begin
  if p_task = p_dep then raise exception 'cycle_detected' using errcode = 'GR001'; end if;
  select root_id, state into v_root, v_state from tasks where id = p_task;
  select root_id into v_root2 from tasks where id = p_dep;
  if v_root is null or v_root2 is null then raise exception 'task_not_found' using errcode = 'GR000'; end if;
  if v_root <> v_root2 then raise exception 'cross_root_dependency' using errcode = 'GR007'; end if;
  perform lock_root(v_root);                          -- сериализует конкурентные add_dep
  select state into v_state from tasks where id = p_task;
  if v_state <> 'pending' then raise exception 'task_not_pending' using errcode = 'GR008'; end if;

  if exists (
    with recursive d as (
      select task_id from task_deps where dep_id = p_task
      union
      select x.task_id from task_deps x join d on x.dep_id = d.task_id)
    select 1 from d where task_id = p_dep) then
    raise exception 'cycle_detected' using errcode = 'GR001';
  end if;

  select c_num(contract, '{budget,max_depth}', 10), c_num(contract, '{budget,max_children}', 20)
    into v_maxd, v_maxc from tasks where id = v_root;

  if (select count(*) from task_deps where dep_id = p_dep) >= v_maxc then
    raise exception 'fanout_exceeded' using errcode = 'GR003';
  end if;

  with recursive up(id, d) as (
    select p_dep, 0
    union
    select x.dep_id, up.d + 1 from task_deps x join up on x.task_id = up.id where up.d <= v_maxd),
  down(id, d) as (
    select p_task, 0
    union
    select x.task_id, down.d + 1 from task_deps x join down on x.dep_id = down.id where down.d <= v_maxd)
  select (select max(d) from up) + 1 + (select max(d) from down) into v_len;
  if v_len > v_maxd then raise exception 'depth_exceeded' using errcode = 'GR002'; end if;

  insert into task_deps (task_id, dep_id) values (p_task, p_dep);
  perform append_event(p_task, 'dep:' || p_dep, 'dep_added', 'planner', jsonb_build_object('dep', p_dep));
end $$;

create function promote_ready() returns int language plpgsql as $$
declare r record; v_n int := 0; v_epoch bigint;
begin
  for r in
    select t.id from tasks t
    where t.state = 'pending'
      and not exists (select 1 from task_deps d join tasks p on p.id = d.dep_id
                      where d.task_id = t.id and p.state <> 'done')
    order by t.id for update skip locked
  loop
    update tasks set state = 'ready', updated_at = now() where id = r.id
      returning lease_epoch into v_epoch;
    perform append_event(r.id, 'promote:' || r.id || ':' || v_epoch, 'promoted', 'scheduler');
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

-- ---------- жизненный цикл воркера ----------
create function claim_task(p_worker text, p_lease_sec int default 300)
returns table (out_task_id uuid, out_contract jsonb, out_epoch bigint,
               out_budget bigint, out_spent bigint)
language plpgsql as $$
declare v_id uuid; v_epoch bigint;
begin
  if p_lease_sec <= 0 then
    raise exception 'lease duration must be positive' using errcode = 'CT001';
  end if;
  update workers set last_seen = now() where id = p_worker;
  if not found then raise exception 'worker_unknown' using errcode = 'WK002'; end if;

  select t.id into v_id
  from tasks t join workers w on w.id = p_worker
  where t.state = 'ready'
    and t.spent_tokens < t.budget_cap
    and t.attempts < c_num(t.contract, '{budget,attempts}', 3)
    and c_num(w.capabilities, '{ram_gb}', 0) >= c_num(t.contract, '{needs,min_ram_gb}', 0)
    and c_num(w.capabilities, '{models,coder_class}', 0) >= c_num(t.contract, '{needs,coder_class}', 0)
    and not exists (select 1 from task_deps d join tasks p on p.id = d.dep_id
                    where d.task_id = t.id and p.state <> 'done')
  order by (select count(*) from jsonb_array_elements_text(
              coalesce(t.contract #> '{needs,affinity_tags}', '[]'::jsonb)) x
            where x = any (w.affinity_tags)) desc,
           t.priority desc, t.created_at, t.id
  for update of t skip locked
  limit 1;

  if v_id is null then return; end if;

  update tasks
     set state = 'leased', lease_owner = p_worker, lease_epoch = lease_epoch + 1,
         lease_until = now() + make_interval(secs => p_lease_sec), updated_at = now()
   where id = v_id returning lease_epoch into v_epoch;
  perform append_event(v_id, 'claim:' || v_id || ':' || v_epoch, 'claimed', p_worker,
                       jsonb_build_object('epoch', v_epoch));
  return query select t.id, t.contract, t.lease_epoch, t.budget_cap, t.spent_tokens
               from tasks t where t.id = v_id;
end $$;

-- Продлевает только действующую аренду; истёкшую «оживить» нельзя.
create function heartbeat(p_task uuid, p_worker text, p_epoch bigint, p_extend_sec int default 300)
returns boolean language plpgsql as $$
begin
  if p_extend_sec <= 0 then
    raise exception 'lease extension must be positive' using errcode = 'CT001';
  end if;
  update tasks set lease_until = now() + make_interval(secs => p_extend_sec), updated_at = now()
   where id = p_task and state = 'leased' and lease_owner = p_worker
     and lease_epoch = p_epoch and lease_until > now();
  if found then update workers set last_seen = now() where id = p_worker; end if;
  return found;
end $$;

create function assert_lease(p_task uuid, p_worker text, p_epoch bigint) returns void
language plpgsql as $$
begin
  perform 1 from tasks
   where id = p_task and state = 'leased' and lease_owner = p_worker
     and lease_epoch = p_epoch and lease_until > now()
   for update;
  if not found then raise exception 'lease_lost' using errcode = 'LS001'; end if;
end $$;

create function save_artifact(p_task uuid, p_worker text, p_epoch bigint, p_ref text,
                              p_storage text, p_content_type text default null,
                              p_size bigint default null)
returns void language plpgsql as $$
begin
  perform assert_lease(p_task, p_worker, p_epoch);
  insert into artifacts (task_id, ref, created_by, lease_epoch, content_type, size_bytes, storage_path)
  values (p_task, p_ref, p_worker, p_epoch, p_content_type, p_size, p_storage)
  on conflict (task_id, ref) do nothing;
  perform append_event(p_task, 'art:' || p_ref, 'artifact_saved', p_worker,
                       jsonb_build_object('ref', p_ref));
end $$;

create function complete_task(p_task uuid, p_worker text, p_epoch bigint,
                              p_result_ref text, p_tokens bigint default 0)
returns text language plpgsql as $$
declare v_new text; v_spent bigint; v_cap bigint;
begin
  perform assert_lease(p_task, p_worker, p_epoch);
  if p_tokens < 0 then
    raise exception 'tokens must be non-negative' using errcode = 'CT001';
  end if;
  if not exists (select 1 from artifacts where task_id = p_task and ref = p_result_ref) then
    raise exception 'artifact_missing' using errcode = 'AR001';
  end if;
  select spent_tokens + p_tokens, budget_cap into v_spent, v_cap from tasks where id = p_task;
  v_new := case when v_spent > v_cap then 'blocked' else 'review' end;
  update tasks
     set state = v_new, result_ref = p_result_ref, spent_tokens = v_spent,
         lease_owner = null, lease_until = null, updated_at = now(),
         block_reason = case when v_new = 'blocked' then 'budget_exhausted' end
   where id = p_task;
  perform append_event(p_task, 'complete:' || p_epoch, 'completed', p_worker,
                       jsonb_build_object('ref', p_result_ref, 'new_state', v_new, 'tokens', p_tokens));
  return v_new;
end $$;

create function submit_review(p_task uuid, p_ref text, p_reviewer text,
                              p_verdict text, p_checks jsonb)
returns text language plpgsql as $$
declare t tasks%rowtype; v_creator text; v_new text;
begin
  select * into t from tasks where id = p_task for update;
  if not found then raise exception 'task_not_found' using errcode = 'GR000'; end if;
  if t.state <> 'review' or t.result_ref is distinct from p_ref then
    raise exception 'review_stale' using errcode = 'RV001';  -- ревью строго привязано к хэшу
  end if;
  select created_by into v_creator from artifacts where task_id = p_task and ref = p_ref;
  if v_creator = p_reviewer then raise exception 'self_review' using errcode = 'RV002'; end if;
  if p_verdict = 'approved' then
    if jsonb_typeof(p_checks) <> 'array'
       or jsonb_array_length(p_checks) < jsonb_array_length(t.contract->'checks')
       or exists (select 1 from jsonb_array_elements(p_checks) e
                  where e->>'status' is distinct from 'pass') then
      raise exception 'checks_failed' using errcode = 'RV003';
    end if;
  end if;
  insert into reviews (task_id, artifact_ref, reviewer, verdict, checks)
  values (p_task, p_ref, p_reviewer, p_verdict, p_checks);

  if p_verdict = 'approved' then v_new := 'done';
  elsif p_verdict = 'changes_requested' then
    v_new := case when t.rework + 1 > c_num(t.contract, '{budget,max_rework}', 3)
                  then 'blocked' else 'ready' end;
  else v_new := 'blocked';
  end if;

  update tasks
     set state = v_new,
         rework = rework + case when p_verdict = 'changes_requested' then 1 else 0 end,
         lease_epoch = lease_epoch + case when v_new = 'ready' then 1 else 0 end,
         block_reason = case when v_new = 'blocked' then
                        case when p_verdict = 'rejected' then 'rejected' else 'max_rework' end end,
         updated_at = now()
   where id = p_task;
  perform append_event(p_task, 'review:' || p_ref || ':' || p_reviewer, 'review_submitted',
                       p_reviewer, jsonb_build_object('verdict', p_verdict, 'new_state', v_new));
  if v_new = 'done' then perform promote_ready(); end if;
  return v_new;
end $$;

-- ---------- сторож и операторские действия ----------
-- attempts растёт только здесь; epoch+1 отсекает зомби-воркера немедленно.
create function reclaim_expired() returns int language plpgsql as $$
declare r record; v_n int := 0; v_next text; v_epoch bigint;
begin
  for r in
    select id, attempts, contract from tasks
    where state = 'leased' and lease_until < now()
    order by id for update skip locked
  loop
    v_next := case when r.attempts + 1 >= c_num(r.contract, '{budget,attempts}', 3)
                   then 'blocked' else 'ready' end;
    update tasks
       set state = v_next, attempts = attempts + 1, lease_epoch = lease_epoch + 1,
           lease_owner = null, lease_until = null, updated_at = now(),
           block_reason = case when v_next = 'blocked' then 'max_attempts' end
     where id = r.id returning lease_epoch into v_epoch;
    perform append_event(r.id, 'reclaim:' || r.id || ':' || v_epoch, 'reclaimed', 'watchdog',
                         jsonb_build_object('new_state', v_next));
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

create function reopen_task(p_task uuid, p_actor text) returns int
language plpgsql as $$
declare r record; v_n int := 0; v_epoch bigint; v_root uuid;
begin
  select root_id into v_root from tasks where id = p_task;
  if v_root is null then raise exception 'task_not_found' using errcode = 'GR000'; end if;
  perform lock_root(v_root);
  update tasks set state = 'ready', lease_epoch = lease_epoch + 1, lease_owner = null,
         lease_until = null, block_reason = null, updated_at = now()
   where id = p_task and state = 'done' returning lease_epoch into v_epoch;
  if not found then raise exception 'not_done' using errcode = 'GR005'; end if;
  perform append_event(p_task, 'reopen:' || p_task || ':' || v_epoch, 'reopened', p_actor);
  for r in
    with recursive sub as (
      select task_id from task_deps where dep_id = p_task
      union
      select d.task_id from task_deps d join sub s on d.dep_id = s.task_id)
    select t.id from tasks t
    where t.id in (select task_id from sub) and t.state in ('ready','leased','review','done')
    order by t.id for update
  loop
    update tasks set state = 'blocked', lease_owner = null, lease_until = null,
           lease_epoch = lease_epoch + 1, block_reason = 'parent_reopened', updated_at = now()
     where id = r.id returning lease_epoch into v_epoch;
    perform append_event(r.id, 'cascade:' || r.id || ':' || v_epoch, 'cascade_blocked', p_actor,
                         jsonb_build_object('parent', p_task));
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

create function unblock_task(p_task uuid, p_actor text) returns text language plpgsql as $$
declare v_epoch bigint;
begin
  update tasks set state = 'pending', attempts = 0, rework = 0, block_reason = null,
         lease_epoch = lease_epoch + 1, updated_at = now()
   where id = p_task and state = 'blocked' returning lease_epoch into v_epoch;
  if not found then raise exception 'not_blocked' using errcode = 'GR009'; end if;
  perform append_event(p_task, 'unblock:' || p_task || ':' || v_epoch, 'unblocked', p_actor);
  perform promote_ready();
  return (select state from tasks where id = p_task);
end $$;

#!/bin/sh # 02-roles.sh — применяет roles.sql после 01-schema.sql. # # Запускается официальным образом postgres из /docker-entrypoint-initdb.d/ # только при пустом каталоге данных (первая инициализация). # Пароли ролей берутся из env (SWARM_PW_*), заданы в docker-compose.yml. set -eu
: "${POSTGRES_USER:?POSTGRES_USER required}" : "${POSTGRES_DB:?POSTGRES_DB required}"
psql -v ON_ERROR_STOP=1 \ -U "$POSTGRES_USER" -d "$POSTGRES_DB" \ -v worker_pw="$SWARM_PW_WORKER" \ -v watchdog_pw="$SWARM_PW_WATCHDOG" \ -v planner_pw="$SWARM_PW_PLANNER" \ -v reviewer_pw="$SWARM_PW_REVIEWER" \ -v operator_pw="$SWARM_PW_OPERATOR" \ -v cli_pw="$SWARM_PW_CLI" \ -f /sql/roles.sql

#!/bin/sh # 03-role-patches.sh — применяет патчи грантов после roles.sql и roles_2b.sql. # # Запускается официальным образом postgres из /docker-entrypoint-initdb.d/ # только при пустом каталоге данных (первая инициализация). # # Порядок инициализации: # 01-schema.sql (schema/schema_v0.sql) # 02-roles.sh (step2/roles.sql) # 03-roles-2b.sh (step2b/roles_2b.sql) # 04-role-patches.sh (этот файл; step2/roles_patch_*.sql) # # roles.sql и roles_2b.sql не меняются (приняты). Новые гранты добавляются # отдельными патч-файлами вида step2/roles_patch_*.sql и подключаются здесь. set -eu
: "${POSTGRES_USER:?POSTGRES_USER required}" : "${POSTGRES_DB:?POSTGRES_DB required}"
for patch in /sql/roles_patch_*.sql; do [ -e "$patch" ] || continue echo "03-role-patches: applying $patch" psql -v ON_ERROR_STOP=1 \ -U "$POSTGRES_USER" -d "$POSTGRES_DB" \ -f "$patch" done

#!/bin/sh # 03-roles-2b.sh — применяет step2b/roles_2b.sql (идентификация воркера) # после roles.sql. # # Запускается официальным образом postgres из /docker-entrypoint-initdb.d/ # только при пустом каталоге данных (первая инициализация). # # Порядок инициализации: # 01-schema.sql (schema/schema_v0.sql) # 02-roles.sh (step2/roles.sql) # 03-roles-2b.sh (этот файл; step2b/roles_2b.sql) # 04-role-patches.sh (step2/roles_patch_*.sql) set -eu
: "${POSTGRES_USER:?POSTGRES_USER required}" : "${POSTGRES_DB:?POSTGRES_DB required}"
psql -v ON_ERROR_STOP=1 \ -U "$POSTGRES_USER" -d "$POSTGRES_DB" \ -v w1_pw="$SWARM_PW_W1" \ -v w2_pw="$SWARM_PW_W2" \ -v w_1_pw="$SWARM_PW_W_1" \ -v gpu_1_pw="$SWARM_PW_GPU_1" \ -f /sql/roles_2b.sql

#!/usr/bin/env bash # Disposable acceptance harness for the schema/RBAC acceptance branch. # This file intentionally does not use docker compose: the database has no # named volume and is removed by the EXIT trap on every path. set -Eeuo pipefail
BASE="" BRANCH="HEAD" WORKTREE="$(pwd)" SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)" FULL_WORKSPACE_TEST=0 ALLOW_BLOCKED=0 LOG_DIR="${TMPDIR:-/tmp}/swarm-dispatcher-acceptance" CONTAINER="" DB_PASSWORD="" LOG_FILE="" SEALED_LOG_FILE="" ATTESTATION_FILE="" EVENT_FILE="" ALLOWLIST_FILE="" FAILURES=0 BLOCKED_COUNT=0 DB_READY=0 TEST_DATABASE_URL="" SANITIZED_TEST_DATABASE_URL="" TEST_DB_HOST="127.0.0.1" TEST_DB_PORT="" TEST_DB_NAME="c2_swarm" TEST_DB_USER="postgres" CREDENTIALS_REDACTED=0
usage() { cat <<'USAGE' Usage: scripts/acceptance_harness.sh --base COMMIT [options]
Options: --base COMMIT Required diff comparison base. --branch REF Ref to check (default: HEAD). --worktree PATH Checkout to inspect (default: current directory). --allowlist-file PATH Exact paths/prefixes (path or path/*, one per line). --log-dir PATH Temporary log directory. --full-workspace-test Require and run cargo test --workspace (release requirement). --allow-blocked Diagnostic mode: allow BLOCKED checks and mark gate CONDITIONAL.
Default is a STRICT release gate: omitting --full-workspace-test records that check as BLOCKED and exits nonzero. Use --allow-blocked only for diagnostics. -h, --help Show this help. USAGE }
while (($#)); do case "$1" in --base) BASE="${2:?--base requires a commit}"; shift 2 ;; --branch) BRANCH="${2:?--branch requires a ref}"; shift 2 ;; --worktree) WORKTREE="${2:?--worktree requires a path}"; shift 2 ;; --allowlist-file) ALLOWLIST_FILE="${2:?--allowlist-file requires a path}"; shift 2 ;; --log-dir) LOG_DIR="${2:?--log-dir requires a path}"; shift 2 ;; --full-workspace-test) FULL_WORKSPACE_TEST=1; shift ;; --allow-blocked) ALLOW_BLOCKED=1; shift ;; -h|--help) usage; exit 0 ;; *) echo "FAIL unknown option: $1" >&2; usage >&2; exit 2 ;; esac done
if [[ -z "$BASE" ]]; then echo "FAIL --base is required" >&2 usage >&2 exit 2 fi
WORKTREE="$(cd "$WORKTREE" && pwd)" mkdir -p "$LOG_DIR" LOG_FILE="$LOG_DIR/harness-$(date -u +%Y%m%dT%H%M%SZ)-$$.log" SEALED_LOG_FILE="${LOG_FILE%.log}.sealed.log" ATTESTATION_FILE="${LOG_FILE%.log}.attestation.json" EVENT_FILE="${LOG_FILE%.log}.events.tsv" touch "$EVENT_FILE" exec > >(tee -a "$LOG_FILE") 2>&1
status() { local state="$1" label="$2" exit_code="${3:-0}" command="${4:-}" printf '%s %s\n' "$state" "$label" printf '%s\t%s\t%s\t%s\n' "$state" "$exit_code" "$label" "$command" >>"$EVENT_FILE" if [[ "$state" == FAIL ]]; then FAILURES=$((FAILURES + 1)) elif [[ "$state" == BLOCKED ]]; then BLOCKED_COUNT=$((BLOCKED_COUNT + 1)) if ((ALLOW_BLOCKED == 0)); then FAILURES=$((FAILURES + 1)) fi fi return 0 }
run_step() { local label="$1"; shift printf 'RUN %s\n' "$label" local command_text command_text="$(printf '%q ' "$@")" printf 'COMMAND %s\n' "$command_text" set +e "$@" local rc=$? set -e if ((rc == 0)); then status PASS "$label" "$rc" "$command_text" else status FAIL "$label (see log)" "$rc" "$command_text" fi return 0 }
run_worktree_step() { local label="$1"; shift printf 'RUN %s\n' "$label" local command_text command_text="(cd $(printf '%q' "$WORKTREE") && $(printf '%q ' "$@"))" printf 'COMMAND %s\n' "$command_text" set +e (cd "$WORKTREE" && "$@") local rc=$? set -e if ((rc == 0)); then status PASS "$label" "$rc" "$command_text" else status FAIL "$label (see log)" "$rc" "$command_text" fi return 0 }
write_attestation() { local base_sha head_sha branch_name timestamp rustc cargo pg_version image_ref image_digest log_sha release_gate base_sha="$(git -C "$WORKTREE" rev-parse "$BASE" 2>/dev/null || printf 'UNRESOLVED')" head_sha="$(git -C "$WORKTREE" rev-parse "$BRANCH" 2>/dev/null || printf 'UNRESOLVED')" branch_name="$(git -C "$WORKTREE" symbolic-ref --short -q HEAD 2>/dev/null || printf '%s' "$BRANCH")" timestamp="$(date -u +%Y-%m-%dT%H:%M:%SZ)" rustc="$(rustc -Vv 2>/dev/null || printf 'UNAVAILABLE')" cargo="$(cargo -V 2>/dev/null || printf 'UNAVAILABLE')" pg_version="${PG_VERSION:-UNAVAILABLE}" image_ref="postgres:16-alpine" image_digest="$(docker image inspect --format '{{index .RepoDigests 0}}' "$image_ref" 2>/dev/null || printf 'UNAVAILABLE')" log_sha="$(sha256sum "$SEALED_LOG_FILE" | awk '{print $1}')" release_gate="$( ((ALLOW_BLOCKED == 1)) && printf 'CONDITIONAL' || printf 'STRICT' )" export ATTESTATION_FILE base_sha head_sha branch_name timestamp rustc cargo pg_version image_ref image_digest log_sha release_gate BLOCKED_COUNT FULL_WORKSPACE_TEST TEST_DB_HOST TEST_DB_PORT TEST_DB_NAME TEST_DB_USER SANITIZED_TEST_DATABASE_URL CREDENTIALS_REDACTED EVENT_FILE SEALED_LOG_FILE python3 - <<'PY' import json, os events = [] with open(os.environ["EVENT_FILE"], encoding="utf-8") as f: for line in f: state, code, label, command = line.rstrip("\n").split("\t", 3) events.append({"status": state, "exit_code": int(code), "label": label, "command": command}) with open(os.environ["ATTESTATION_FILE"], "w", encoding="utf-8") as f: json.dump({ "format": "swarm-dispatcher-acceptance-attestation/v1", "base_sha": os.environ["base_sha"], "branch": os.environ["branch_name"], "head_sha": os.environ["head_sha"], "timestamp_utc": os.environ["timestamp"], "release_gate": os.environ["release_gate"], "blocked_count": int(os.environ["BLOCKED_COUNT"]), "full_workspace_test_requested": bool(int(os.environ["FULL_WORKSPACE_TEST"])), "toolchain": {"rustc_Vv": os.environ["rustc"], "cargo": os.environ["cargo"]}, "postgres": {"server_version": os.environ["pg_version"], "image": os.environ["image_ref"], "image_digest": os.environ["image_digest"]}, "test_database": {"dsn": os.environ.get("SANITIZED_TEST_DATABASE_URL", "UNAVAILABLE"), "host": os.environ.get("TEST_DB_HOST", "UNAVAILABLE"), "port": os.environ.get("TEST_DB_PORT", "UNAVAILABLE"), "db": os.environ.get("TEST_DB_NAME", "UNAVAILABLE"), "user": os.environ.get("TEST_DB_USER", "UNAVAILABLE")}, "credentials_redacted": bool(int(os.environ["CREDENTIALS_REDACTED"])), "statuses": events, "log": {"path": os.environ["SEALED_LOG_FILE"], "sha256": os.environ["log_sha"]}, "artifacts": [{"path": os.environ["SEALED_LOG_FILE"], "sha256": os.environ["log_sha"]}], }, f, indent=2, sort_keys=True) f.write("\n") PY }
cleanup() { local rc=$? if [[ -n "$CONTAINER" ]] && command -v docker >/dev/null 2>&1; then docker rm -f "$CONTAINER" >/dev/null 2>&1 || true printf 'PASS disposable container cleaned: %s\n' "$CONTAINER" fi PG_VERSION="${PG_VERSION:-UNAVAILABLE}" if ((rc != 0 || FAILURES != 0)); then printf 'FAIL acceptance harness completed with %d failure(s); log: %s; attestation: %s\n' "$FAILURES" "$LOG_FILE" "$ATTESTATION_FILE" else printf 'PASS acceptance harness complete; log: %s; attestation: %s\n' "$LOG_FILE" "$ATTESTATION_FILE" fi # Remove the ephemeral credential before sealing generated artifacts. if [[ -n "$DB_PASSWORD" && -f "$LOG_FILE" ]]; then sed -i "s|$DB_PASSWORD|[REDACTED]|g" "$LOG_FILE" if grep -Fq "$DB_PASSWORD" "$LOG_FILE"; then printf 'FAIL temporary database password remains in log\n' FAILURES=$((FAILURES + 1)) else CREDENTIALS_REDACTED=1 printf 'PASS temporary database password absent from log\n' fi fi # Seal the complete sanitized log before generating JSON; attestation generation emits no log output. cp -- "$LOG_FILE" "$SEALED_LOG_FILE" write_attestation exit "$((rc != 0 ? rc : (FAILURES > 0 ? 1 : 0)))" } trap cleanup EXIT
check_diff_scope() { local path rule prefix matched if [[ -n "$ALLOWLIST_FILE" ]]; then [[ -f "$ALLOWLIST_FILE" ]] || { printf 'allowlist file not found: %s\n' "$ALLOWLIST_FILE"; return 1; } fi while IFS= read -r path; do [[ -z "$path" ]] && continue matched=0 if [[ -n "$ALLOWLIST_FILE" ]]; then while IFS= read -r rule || [[ -n "$rule" ]]; do rule="${rule%%#*}" rule="$(printf '%s' "$rule" | sed 's/^[[:space:]]*//; s/[[:space:]]*$//')" [[ -z "$rule" ]] && continue if [[ "$rule" == */\* ]]; then prefix="${rule%/*}/" [[ "$path" == "$prefix"* ]] && matched=1 else [[ "$path" == "$rule" ]] && matched=1 fi ((matched)) && break done < "$ALLOWLIST_FILE" else [[ "$path" == scripts/acceptance_harness.sh || "$path" == docs/audit/* ]] && matched=1 fi ((matched)) || { printf 'out-of-scope path: %s\n' "$path"; return 1; } done < <(git -C "$WORKTREE" diff --name-only "$BASE..$BRANCH") }
shell_checks() { local file bash -n "$SCRIPT_DIR/acceptance_harness.sh" while IFS= read -r file; do bash -n "$file" done < <(find "$WORKTREE/scripts" -maxdepth 1 -type f -name '*.sh' -print) if command -v shellcheck >/dev/null 2>&1; then shellcheck "$SCRIPT_DIR/acceptance_harness.sh" else status BLOCKED "shellcheck unavailable (bash -n passed)" fi }
compose_check() { local env_file rendered env_file="$(mktemp)" cat >"$env_file" <<'ENV' DB_PASSWORD=dummy_db_password SWARM_PW_WORKER=dummy_worker_password SWARM_PW_WATCHDOG=dummy_watchdog_password SWARM_PW_PLANNER=dummy_planner_password SWARM_PW_REVIEWER=dummy_reviewer_password SWARM_PW_OPERATOR=dummy_operator_password SWARM_PW_CLI=dummy_cli_password SWARM_PW_W1=dummy_w1_password SWARM_PW_W2=dummy_w2_password SWARM_PW_W_1=dummy_w_1_password SWARM_PW_GPU_1=dummy_gpu_1_password ENV rendered="$(mktemp)" docker compose --env-file "$env_file" -f "$WORKTREE/docker-compose.yml" config >"$rendered" 2>/dev/null || true rm -f "$env_file" [[ -s "$rendered" ]] || { rm -f "$rendered"; return 1; } RENDERED_COMPOSE_FILE="$rendered" compose_security_acceptance local rc=$? rm -f "$rendered" return $rc }
# P0-3: pin the worker container boundary in a verifiable check, not just docs. compose_security_acceptance() { python3 - <<'PY' import os, sys, yaml with open(os.environ["RENDERED_COMPOSE_FILE"], encoding="utf-8") as f: cfg = yaml.safe_load(f) or {} services = cfg.get("services", {}) workers = [n for n in services if n.startswith("worker-")] def fail(msg): print(f"FAIL {msg}") sys.exit(1) if not workers: fail("no worker-* service in compose") for name in sorted(workers): svc = services[name] if svc.get("read_only") is not True: fail(f"{name}: read_only must be true") if "ALL" not in (svc.get("cap_drop") or []): fail(f"{name}: cap_drop must include ALL") sec = svc.get("security_opt") or [] if not any("no-new-privileges" in s for s in sec): fail(f"{name}: no-new-privileges missing") for vol in svc.get("volumes") or []: src = vol if isinstance(vol, str) else (vol.get("source") or "") if "docker.sock" in str(src): fail(f"{name}: docker.sock must not be mounted by default") if svc.get("privileged") is True: fail(f"{name}: privileged must not be set") if svc.get("network_mode") == "host": fail(f"{name}: host network mode not allowed") print("PASS worker container boundary pinned: " + ", ".join(sorted(workers))) PY }
pg() { local user="$1" password="$2"; shift 2 docker exec -e PGPASSWORD="$password" "$CONTAINER" psql -X -v ON_ERROR_STOP=1 -U "$user" -d c2_swarm "$@" }
expect_failure() { local label="$1"; shift if "$@" >/dev/null 2>&1; then status FAIL "$label unexpectedly succeeded" return 1 fi status PASS "$label" }
provision_database() { local failures_before=$FAILURES command -v docker >/dev/null 2>&1 DB_PASSWORD="c2_$(openssl rand -hex 20)" CONTAINER="c2_acceptance_${USER:-user}_$$" CONTAINER="${CONTAINER//[^a-zA-Z0-9_.-]/_}" local common_args=( --name "$CONTAINER" -e POSTGRES_DB=c2_swarm -e POSTGRES_USER=postgres -e "POSTGRES_PASSWORD=$DB_PASSWORD" -p 127.0.0.1::5432 -v "$WORKTREE/schema/schema_v0.sql:/c2/schema.sql:ro" -v "$WORKTREE/step2/roles.sql:/c2/roles.sql:ro" -v "$WORKTREE/step2b/roles_2b.sql:/c2/roles_2b.sql:ro" -v "$WORKTREE/step2/roles_patch_planner_status.sql:/c2/patch_planner.sql:ro" -v "$WORKTREE/step2/roles_patch_tool_call_audit.sql:/c2/patch_tool_call.sql:ro" -v "$WORKTREE/step2/roles_patch_submit_review.sql:/c2/patch_review.sql:ro" ) docker run -d "${common_args[@]}" postgres:16-alpine >/dev/null PG_VERSION="$(docker exec "$CONTAINER" postgres --version)" TEST_DB_PORT="$(docker port "$CONTAINER" 5432/tcp | awk -F: 'NR == 1 {print $NF}')" [[ "$TEST_DB_PORT" =~ ^[0-9]+$ ]] TEST_DATABASE_URL="host=localhost port=${TEST_DB_PORT} user=postgres password=${DB_PASSWORD} dbname=${TEST_DB_NAME}" SANITIZED_TEST_DATABASE_URL="host=localhost port=${TEST_DB_PORT} user=postgres password=[REDACTED] dbname=${TEST_DB_NAME}" [[ "$TEST_DATABASE_URL" == *"password=${DB_PASSWORD}"* ]] [[ "$SANITIZED_TEST_DATABASE_URL" != *"${DB_PASSWORD}"* ]] local ready=0 for _ in {1..60}; do if docker exec -e PGPASSWORD="$DB_PASSWORD" "$CONTAINER" \ psql -X -U postgres -d c2_swarm -c 'select 1' >/dev/null 2>&1; then ready=1 break fi sleep 1 done ((ready == 1))
# Apply exactly the repository's accepted order, with ON_ERROR_STOP on each file. pg postgres "$DB_PASSWORD" -f /c2/schema.sql pg postgres "$DB_PASSWORD" -v worker_pw=c2_worker -v watchdog_pw=c2_watchdog \ -v planner_pw=c2_planner -v reviewer_pw=c2_reviewer -v operator_pw=c2_operator \ -v cli_pw=c2_cli -f /c2/roles.sql pg postgres "$DB_PASSWORD" -v w1_pw=c2_w1 -v w2_pw=c2_w2 -v w_1_pw=c2_w_1 \ -v gpu_1_pw=c2_gpu_1 -f /c2/roles_2b.sql pg postgres "$DB_PASSWORD" -f /c2/patch_planner.sql pg postgres "$DB_PASSWORD" -f /c2/patch_tool_call.sql pg postgres "$DB_PASSWORD" -f /c2/patch_review.sql DB_READY=1 status PASS "disposable PostgreSQL 16 provisioned and initialized" }
database_acceptance() { local failures_before=$FAILURES [[ "$DB_READY" == 1 ]]
local common_worker_login worker_login common_worker_login="$(pg postgres "$DB_PASSWORD" -Atc "select rolcanlogin from pg_roles where rolname='swarm_worker'")" worker_login="$(pg postgres "$DB_PASSWORD" -Atc "select rolcanlogin from pg_roles where rolname='swarm_worker_w1'")" if [[ "$common_worker_login" == f ]]; then status PASS "common swarm_worker is NOLOGIN" else status FAIL "common swarm_worker must be NOLOGIN (P0 RBAC fix is absent from this branch)" fi if [[ "$worker_login" == t ]]; then status PASS "per-worker role swarm_worker_w1 is LOGIN" else status FAIL "per-worker role swarm_worker_w1 must be LOGIN" fi
pg swarm_worker_w1 c2_w1 -c "select register_worker('w1', '{\"ram_gb\":16}'::jsonb)" status PASS "per-worker register_worker works" expect_failure "worker identity spoofing is rejected" pg swarm_worker_w1 c2_w1 -c "select register_worker('w2', '{\"ram_gb\":16}'::jsonb)" expect_failure "cli claim_task is denied" pg swarm_cli c2_cli -c "select claim_task('w1', 10)" expect_failure "SET ROLE spoofing is denied" pg swarm_worker_w1 c2_w1 -c "set role swarm_worker_w2" ((FAILURES == failures_before)) }
review_gate_acceptance() { local failures_before=$FAILURES [[ "$DB_READY" == 1 ]] local suite local suites=( "step2/test_roles.py|RBAC role separation + catalog invariants (P0 #3/#4)" "step2b/test_roles_2b.py|worker identity, SET ROLE, id collisions (P0 #4)" "step2/test_review_gate.py|review-gate negative tests (P0 #5)" "tests/test_v0.py|state machine: lease/epoch, add_dep, reopen cascade (P0 #6/#7)" ) for suite in "${suites[@]}"; do [[ -f "$WORKTREE/${suite%%|*}" ]] || { status BLOCKED "missing test suite: ${suite%%|*}"; return 0; } done local py="$WORKTREE/.venv/bin/python" if [[ ! -x "$py" ]]; then if command -v uv >/dev/null 2>&1; then (cd "$WORKTREE" && uv venv --quiet .venv && uv pip install --quiet --python .venv/bin/python pytest psycopg2-binary) || true fi fi if [[ ! -x "$py" ]]; then status BLOCKED "python venv with pytest+psycopg2 unavailable (install uv or .venv)" return 0 fi export ROLES_DB=c2_swarm ROLES_HOST=127.0.0.1 ROLES_PORT=$TEST_DB_PORT ADMIN_PW="$DB_PASSWORD" export SWARM_PW_W1=c2_w1 SWARM_PW_W2=c2_w2 SWARM_PW_W_1=c2_w_1 SWARM_PW_GPU_1=c2_gpu_1 export SWARM_PW_WORKER=c2_worker SWARM_PW_WATCHDOG=c2_watchdog SWARM_PW_PLANNER=c2_planner export SWARM_PW_REVIEWER=c2_reviewer SWARM_PW_OPERATOR=c2_operator SWARM_PW_CLI=c2_cli # tests/test_v0.py speaks PGDSN (superuser): reuse the disposable DSN. export PGDSN="dbname=c2_swarm user=postgres host=127.0.0.1 port=$TEST_DB_PORT password=$DB_PASSWORD" for suite in "${suites[@]}"; do run_worktree_step "${suite##*|} on patched c2_ database" \ "$py" -m pytest -q "${suite%%|*}" done unset ROLES_DB ROLES_HOST ROLES_PORT ADMIN_PW PGDSN unset SWARM_PW_W1 SWARM_PW_W2 SWARM_PW_W_1 SWARM_PW_GPU_1 SWARM_PW_WORKER SWARM_PW_WATCHDOG unset SWARM_PW_PLANNER SWARM_PW_REVIEWER SWARM_PW_OPERATOR SWARM_PW_CLI ((FAILURES == failures_before)) }
run_step "diff allowlist ($BASE..$BRANCH)" check_diff_scope run_step "git diff --check" git -C "$WORKTREE" diff --check "$BASE..$BRANCH" run_step "shell syntax checks" shell_checks if command -v docker >/dev/null 2>&1; then run_step "compose config with dummy environment" compose_check run_step "provision disposable PostgreSQL 16 before Rust tests" provision_database else status BLOCKED "docker unavailable: compose config and database acceptance not run" fi if command -v cargo >/dev/null 2>&1; then run_worktree_step "Rust library/unit tests" cargo test --workspace --lib --locked -- --test-threads=1 else status BLOCKED "cargo unavailable: Rust unit tests not run" fi if ((FULL_WORKSPACE_TEST)); then if ((DB_READY == 1)); then export TEST_DATABASE_URL export DATABASE_URL="$TEST_DATABASE_URL" run_worktree_step "required full workspace test with disposable c2_ database" cargo test --workspace --locked -- --test-threads=1 else status BLOCKED "full workspace test blocked: disposable c2_ database is not ready" fi else status BLOCKED "full workspace test not requested (use --full-workspace-test for release gate)" fi if command -v docker >/dev/null 2>&1; then run_step "RBAC smoke on disposable c2_ database" database_acceptance run_step "RBAC/path/review Python suites on disposable c2_ database" review_gate_acceptance fi

#!/usr/bin/env python3 """Собирает XML-бандл всех скриптов репозитория для аудита.
Только чтение. Секреты (.env) НЕ включаются — только .env.example. Выход: docs/audit/SCRIPTS_BUNDLE_v0.4.xml """ from __future__ import annotations
import hashlib import os import subprocess import sys from datetime import datetime, timezone from pathlib import Path from xml.sax.saxutils import escape, quoteattr
REPO = Path(__file__).resolve().parent.parent OUT_DIR = REPO / "docs" / "audit" OUT_XML = OUT_DIR / "SCRIPTS_BUNDLE_v0.4.xml"
# (путь, роль, язык) FILES = [ # --- скрипты инициализации --- ("scripts/02-roles.sh", "init", "bash"), ("scripts/03-roles-2b.sh", "init", "bash"), ("scripts/03-role-patches.sh", "init", "bash"), # --- схема и роли (SQL) --- ("schema/schema_v0.sql", "schema", "sql"), ("step2/roles.sql", "roles", "sql"), ("step2/roles_patch_planner_status.sql", "roles-patch", "sql"), ("step2/roles_patch_tool_call_audit.sql", "roles-patch", "sql"), ("step2b/roles_2b.sql", "roles", "sql"), ("step2b/roles_2b_patch_section3.sql", "roles-patch", "sql"), # --- контейнеризация --- ("Dockerfile", "container", "dockerfile"), ("sandbox/Dockerfile", "container", "dockerfile"), ("docker-compose.yml", "container", "yaml"), # --- тесты --- ("tests/test_v0.py", "test", "python"), ("step2/test_roles.py", "test", "python"), ("step2b/test_roles_2b.py", "test", "python"), # --- конфиг без секретов --- (".env.example", "config", "dotenv"), # --- вспомогательное --- ("rust_fixes/dispatcher.rs", "patch", "rust"), ]
FORBIDDEN = {".env", ".env.bak.1791466553"}
def sha256(path: Path) -> str: h = hashlib.sha256() with path.open("rb") as fh: for chunk in iter(lambda: fh.read(65536), b""): h.update(chunk) return h.hexdigest()
def md5(path: Path) -> str: h = hashlib.md5() with path.open("rb") as fh: for chunk in iter(lambda: fh.read(65536), b""): h.update(chunk) return h.hexdigest()
def git_info() -> dict: def run(*args): try: return subprocess.run( ["git", *args], cwd=REPO, capture_output=True, text=True, timeout=10 ) except Exception: return None
r = run("rev-parse", "HEAD") if r is None or r.returncode != 0: return {"is_git": "false", "note": "not a git repository"} return { "is_git": "true", "head": r.stdout.strip(), "branch": (run("rev-parse", "--abbrev-ref", "HEAD") or type("x", (), {"stdout": ""})).stdout.strip(), "dirty": "true" if (run("status", "--porcelain") and run("status", "--porcelain").stdout.strip()) else "false", }
def main() -> int: OUT_DIR.mkdir(parents=True, exist_ok=True) now = datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds")
entries = [] missing = [] for rel, role, lang in FILES: p = REPO / rel if rel in FORBIDDEN or not p.is_file(): missing.append(rel) continue raw = p.read_bytes() try: text = raw.decode("utf-8") except UnicodeDecodeError: text = raw.decode("utf-8", errors="replace") entries.append( { "path": rel, "role": role, "lang": lang, "bytes": len(raw), "lines": text.count("\n") + (0 if text.endswith("\n") else 1), "sha256": sha256(p), "md5": md5(p), "text": text, } )
total_bytes = sum(e["bytes"] for e in entries) gi = git_info()
out = [] out.append('<?xml version="1.0" encoding="UTF-8"?>') out.append( '<audit-bundle schema="swarm-dispatcher.audit-bundle.v1" ' f'generated={quoteattr(now)} generator={quoteattr("scripts/build_audit_bundle.py")}>' ) out.append(" <project>") out.append(f" <name>swarm-dispatcher</name>") out.append(f" <root>{escape(str(REPO))}</root>") out.append(f" <git is_git={quoteattr(gi['is_git'])}" + (f" head={quoteattr(gi.get('head',''))} branch={quoteattr(gi.get('branch',''))} dirty={quoteattr(gi.get('dirty',''))}/>" if gi["is_git"] == "true" else "") + ("" if gi["is_git"] == "true" else f"><note>{escape(gi.get('note',''))}</note></git>")) out.append(" </project>") out.append(" <manifest>") out.append(f" <files count=\"{len(entries)}\" total_bytes=\"{total_bytes}\"/>") out.append(" <excluded>") out.append(" <file path=\".env\" reason=\"secrets\"/>") out.append(" <file path=\".env.bak.*\" reason=\"secrets\"/>") out.append(" <dir path=\"target/\" reason=\"build artifacts\"/>") out.append(" <dir path=\".venv/\" reason=\"virtualenv\"/>") out.append(" </excluded>") out.append(" <index>") for e in entries: out.append( f' <entry path={quoteattr(e["path"])} role={quoteattr(e["role"])} ' f'lang={quoteattr(e["lang"])} bytes="{e["bytes"]}" lines="{e["lines"]}" ' f'sha256={quoteattr(e["sha256"])} md5={quoteattr(e["md5"])}/>' ) out.append(" </index>") out.append(" </manifest>") out.append(" <files>") for e in entries: out.append( f' <file path={quoteattr(e["path"])} role={quoteattr(e["role"])} ' f'lang={quoteattr(e["lang"])} bytes="{e["bytes"]}" lines="{e["lines"]}" ' f'sha256={quoteattr(e["sha256"])} md5={quoteattr(e["md5"])}>' ) # CDATA, кроме случая когда текст содержит ]]> # Trailing blanks are stripped: embedded REPORT_*.md carry markdown # hard-breaks (two trailing spaces) which would otherwise land in the # bundle and trip `git diff --check` on any regenerated artifact. body = "\n".join(line.rstrip() for line in e["text"].rstrip("\n").split("\n")) if "]]>" in body: out.append(" <content encoding=\"xml-escaped\">") out.append(escape(body)) out.append(" </content>") else: out.append(" <content><![CDATA[") out.append(body) out.append("]]></content>") out.append(" </file>") out.append(" </files>") out.append("</audit-bundle>")
OUT_XML.write_text("\n".join(out) + "\n", encoding="utf-8") print(f"OK {OUT_XML}") print(f" files={len(entries)} total_bytes={total_bytes}") print(f" md5={md5(OUT_XML)} sha256={sha256(OUT_XML)}") if missing: print(f" MISSING: {', '.join(missing)}", file=sys.stderr) return 0
if __name__ == "__main__": raise SystemExit(main())

#!/usr/bin/env python3
"""Собирает полный аудит-бандл проекта (весь код) в XML, по томам.

Тома:
  code  — Rust-исходники, тесты, Cargo-манифесты, фикстуры
  infra — схема/роли SQL, init-скрипты, Dockerfile/compose, конфиги без секретов
  docs  — документация проекта (docs/**, кроме писем inbound) + корневые отчёты

Только чтение. Секреты (.env*) и бинарники (.docx/.png) исключены.
Выход: docs/audit/PROJECT_<VOLUME>_BUNDLE_v0.4.xml
"""
from __future__ import annotations

import hashlib
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path
from xml.sax.saxutils import escape, quoteattr

REPO = Path(__file__).resolve().parent.parent
OUT_DIR = REPO / "docs" / "audit"

EXCL_DIRS = {"target", ".venv", "__pycache__", ".git", "node_modules",
             ".pytest_cache", ".mypy_cache"}
EXCL_FILES = {".env", ".env.bak.1791466553"}
BINARY_SUFFIX = {".docx", ".png", ".jpg", ".jpeg", ".gif", ".pdf", ".zip",
                 ".gz", ".tar", ".rlib", ".rmeta", ".o", ".so"}

# volume -> (описание, [пути-файлы] или корневые префиксы для рекурсии)
VOLUMES: dict[str, dict] = {
    "CODE": {
        "title": "Код проекта (Rust + тесты + манифесты)",
        "globs": ["crates/**/*.rs", "crates/**/Cargo.toml", "Cargo.toml",
                  "Cargo.lock", "crates/**/*.json"],
    },
    "INFRA": {
        "title": "Инфраструктура (SQL, init-скрипты, контейнеры, конфиг)",
        "globs": ["schema/*", "step2/*", "step2b/*", "scripts/*",
                  "docker-compose.yml", "Dockerfile", ".env.example",
                  ".dockerignore", ".gitignore", "LICENSE", "tests/*.py"],
    },
    "DOCS": {
        "title": "Документация и отчёты (без писем history/inbound)",
        "globs": ["docs/**/*.md", "*.md", "docs/history/*.md"],
        "exclude_prefix": ["docs/history/inbound/", "docs/audit/"],
    },
    "DOCS_CORE": {
        "title": "Ключевая документация (ТЗ, архитектура, ограничения, отчёты)",
        "globs": ["docs/TZ_*.md", "docs/ARCHITECTURE.md",
                  "docs/KNOWN_LIMITATIONS.md", "docs/PROJECT_STATE.md",
                  "docs/METHODOLOGY.md", "docs/VERIFICATION_LOG.md",
                  "README.md", "CHANGELOG.md", "RESUME.md", "MANIFEST.md",
                  "REPORT_*.md", "docs/audit/AUDITOR_BRIEF_v0.4.md"],
    },
}


def sha256(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def md5(b: bytes) -> str:
    return hashlib.md5(b).hexdigest()


def file_digest(p: Path, algo: str) -> str:
    h = hashlib.new(algo)
    with p.open("rb") as fh:
        for chunk in iter(lambda: fh.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def git_info() -> dict:
    try:
        r = subprocess.run(["git", "rev-parse", "HEAD"], cwd=REPO,
                           capture_output=True, text=True, timeout=10)
        if r.returncode == 0:
            return {"is_git": "true", "head": r.stdout.strip()}
    except Exception:
        pass
    return {"is_git": "false", "note": "not a git repository"}


def collect(vol: dict) -> list[Path]:
    seen: set[Path] = set()
    ex_pfx = vol.get("exclude_prefix", [])
    for g in vol["globs"]:
        for p in sorted(REPO.glob(g)):
            if not p.is_file():
                continue
            if set(p.relative_to(REPO).parts) & EXCL_DIRS:
                continue
            if p.name in EXCL_FILES or p.suffix in BINARY_SUFFIX:
                continue
            rel = p.relative_to(REPO).as_posix()
            if any(rel.startswith(x) for x in ex_pfx):
                continue
            seen.add(p)
    return sorted(seen, key=lambda p: p.relative_to(REPO).as_posix())


def lang_of(p: Path) -> str:
    n = p.name
    if n == "Dockerfile":
        return "dockerfile"
    if n == "Cargo.toml" or n == "Cargo.lock":
        return "toml"
    if n.startswith(".env"):
        return "dotenv"
    return {".rs": "rust", ".sql": "sql", ".sh": "bash", ".py": "python",
            ".md": "markdown", ".yml": "yaml", ".yaml": "yaml",
            ".json": "json", ".toml": "toml"}.get(p.suffix, "text")


def build_volume(name: str, vol: dict) -> tuple[Path, int, int]:
    files = collect(vol)
    entries = []
    for p in files:
        raw = p.read_bytes()
        text = raw.decode("utf-8", errors="replace")
        entries.append({
            "path": p.relative_to(REPO).as_posix(), "lang": lang_of(p),
            "bytes": len(raw), "lines": text.count("\n") + (0 if text.endswith("\n") else 1),
            "sha256": sha256(raw), "md5": md5(raw), "text": text,
        })
    total = sum(e["bytes"] for e in entries)
    now = datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds")
    gi = git_info()
    out = ['<?xml version="1.0" encoding="UTF-8"?>',
           f'<audit-volume schema="swarm-dispatcher.audit-bundle.v2" volume={quoteattr(name)} '
           f'generated={quoteattr(now)} generator="scripts/build_project_bundle.py">',
           f'  <title>{escape(vol["title"])}</title>',
           f'  <project>swarm-dispatcher</project>',
           f'  <root>{escape(str(REPO))}</root>',
           f'  <git is_git={quoteattr(gi["is_git"])}'
           + (f' head={quoteattr(gi.get("head",""))}/>' if gi["is_git"] == "true"
              else f'><note>{escape(gi.get("note",""))}</note></git>'),
           '  <manifest>',
           f'    <files count="{len(entries)}" total_bytes="{total}"/>',
           '    <excluded>',
           '      <file path=".env*" reason="secrets"/>',
           '      <dir path="target/" reason="build artifacts"/>',
           '      <dir path=".venv/" reason="virtualenv"/>',
           '      <file path="*.docx|*.png" reason="binary"/>',
           '    </excluded>',
           '    <index>']
    for e in entries:
        out.append(f'      <entry path={quoteattr(e["path"])} lang={quoteattr(e["lang"])} '
                   f'bytes="{e["bytes"]}" lines="{e["lines"]}" '
                   f'sha256={quoteattr(e["sha256"])} md5={quoteattr(e["md5"])}/>')
    out += ['    </index>', '  </manifest>', '  <files>']
    for e in entries:
        out.append(f'    <file path={quoteattr(e["path"])} lang={quoteattr(e["lang"])} '
                   f'bytes="{e["bytes"]}" lines="{e["lines"]}" '
                   f'sha256={quoteattr(e["sha256"])} md5={quoteattr(e["md5"])}>')
        if "]]>" in e["text"]:
            # XML-escaped body: strip trailing blanks per line for the same reason.
            body = "\n".join(line.rstrip() for line in e["text"].rstrip("\n").split("\n"))
            out += ['      <content encoding="xml-escaped">', escape(body),
                    '      </content>']
        else:
            # Strip trailing blanks: the embedded files (e.g. REPORT_*.md with
            # markdown hard-breaks) would otherwise put trailing whitespace into
            # the bundle, which trips `git diff --check` on any regenerated
            # artifact. The bundle is an audit snapshot of content, not of
            # insignificant line padding.
            body = "\n".join(line.rstrip() for line in e["text"].rstrip("\n").split("\n"))
            out += ['      <content><![CDATA[', body, ']]></content>']
        out.append('    </file>')
    out += ['  </files>', '</audit-volume>']

    dest = OUT_DIR / f"PROJECT_{name}_BUNDLE_v0.4.xml"
    dest.write_text("\n".join(out) + "\n", encoding="utf-8")
    return dest, len(entries), total


def main() -> int:
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    rows = []
    for name, vol in VOLUMES.items():
        dest, n, total = build_volume(name, vol)
        rows.append((name, dest, n, total, dest.stat().st_size,
                     file_digest(dest, "sha256"), file_digest(dest, "md5")))
        print(f"OK {name:6s} {dest.name}  files={n} bytes={total} "
              f"xml={dest.stat().st_size}")
    print()
    for name, dest, n, total, xb, s, m in rows:
        print(f"{name}: files={n} src_bytes={total} xml_bytes={xb}")
        print(f"   sha256={s}")
        print(f"   md5={m}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

-- swarm roles v0.2: горизонтальное разделение прав.
-- Запуск (суперпользователем, ПОСЛЕ schema_v0.sql):
--   psql -v ON_ERROR_STOP=1 -d swarm \
--        -v worker_pw=... -v watchdog_pw=... -v planner_pw=... \
--        -v reviewer_pw=... -v operator_pw=... -v cli_pw=... -f roles.sql
-- Скрипт идемпотентен. Ничего из того, что делает schema_v0.sql, он не меняет по смыслу:
-- только владельца объектов, режим исполнения функций и права на них.

-- 1. Владелец объектов: не суперпользователь и без входа. SECURITY DEFINER-функции
--    исполняются от его имени, поэтому даже ошибка в функции не даёт прав суперпользователя.
select 'create role swarm_owner nologin'
 where not exists (select 1 from pg_roles where rolname = 'swarm_owner') \gexec

-- 2. Сервисные роли: только вход, никаких привилегий.
select format('create role %I login nosuperuser nocreatedb nocreaterole', r)
  from unnest(array['swarm_worker','swarm_watchdog','swarm_planner',
                    'swarm_reviewer','swarm_operator','swarm_cli']) r
 where not exists (select 1 from pg_roles where rolname = r) \gexec

-- Общая worker-роль содержит права-членство, но не является login identity.
alter role swarm_worker nologin;

alter role swarm_worker   password :'worker_pw';
alter role swarm_watchdog password :'watchdog_pw';
alter role swarm_planner  password :'planner_pw';
alter role swarm_reviewer password :'reviewer_pw';
alter role swarm_operator password :'operator_pw';
alter role swarm_cli      password :'cli_pw';

-- swarm_cli: учебная роль для человека-оператора с CLI (seed, review, reopen).
-- Это членство, а не отдельные права. К функциям воркера доступа у неё нет.
grant swarm_planner, swarm_reviewer, swarm_operator to swarm_cli;

-- 2b. Чтение для оператора: прямого доступа к таблицам нет ни у кого, поэтому статус отдаётся
--     функцией. Поля ограничены (нет contract, нет артефактов), чтобы не светить лишнее.
create or replace function task_status(p_limit int default 200)
returns table (id uuid, root_id uuid, state text, lease_epoch bigint, lease_owner text,
               attempts int, rework int, block_reason text, updated_at timestamptz)
language sql stable as $$
  select t.id, t.root_id, t.state, t.lease_epoch, t.lease_owner, t.attempts, t.rework,
         t.block_reason, t.updated_at
    from tasks t order by t.updated_at desc, t.id limit least(greatest(p_limit, 1), 1000)
$$;

-- 3. Передать владение таблицам (индексы и привязанные sequence переходят вместе с таблицей)
--    и всем функциям схемы.
do $$
declare r record;
begin
  for r in select c.relname from pg_class c join pg_namespace n on n.oid = c.relnamespace
            where n.nspname = 'public' and c.relkind = 'r' loop
    execute format('alter table public.%I owner to swarm_owner', r.relname);
  end loop;
  for r in select p.oid::regprocedure as sig from pg_proc p
            join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public'
             and not exists (select 1 from pg_depend d where d.objid = p.oid and d.deptype = 'e') loop
    execute format('alter function %s owner to swarm_owner', r.sig);
    -- 4. Исполнение от имени владельца + защита от подмены объектов через search_path
    --    (pg_temp последним: временная таблица с именем tasks ничего не перекроет).
    execute format('alter function %s security definer set search_path = public, pg_temp', r.sig);
  end loop;
end $$;

-- 5. Закрыть всё по умолчанию.
revoke all on schema public from public;
grant usage on schema public to swarm_owner, swarm_worker, swarm_watchdog,
      swarm_planner, swarm_reviewer, swarm_operator;
revoke all on all tables    in schema public from public;
revoke all on all sequences in schema public from public;
revoke all on all functions in schema public from public;

-- 6. Выдать нужное. Внутренние функции (append_event, assert_lease, lock_root,
--    validate_contract, event_hash, c_num) не выдаются никому: журнал нельзя подделать снаружи.
grant execute on function claim_task, heartbeat, save_artifact, complete_task, register_worker
  to swarm_worker;
grant execute on function reclaim_expired, promote_ready to swarm_watchdog;
grant execute on function add_task, add_dep, promote_ready to swarm_planner;
grant execute on function submit_review, verify_chain to swarm_reviewer;
grant execute on function reopen_task, unblock_task, verify_chain, task_status to swarm_operator;

-- Patch: strict review-gate verification in submit_review (P0 #5).
--
-- Problem (audit v0.6.0-mvp-rc1): the `approved` branch compared review
-- checks by *length only*:
--
--   if jsonb_array_length(p_checks) < jsonb_array_length(t.contract->'checks')
--      or exists (... e->>'status' is distinct from 'pass')
--
-- That lets a reviewer bypass the gates by submitting N fake
-- `{"status":"pass"}` items with no matching `type`, e.g.:
--
--   contract.checks = [{"type":"unit"},{"type":"lint"}]
--   p_checks        = [{"status":"pass"},{"status":"pass"}]   -- must now fail RV003
--
-- Fix: every required check type from `contract.checks` must have at least one
-- item in `p_checks` with the same `type` AND `status = 'pass'`. Extra passing
-- checks are allowed. Missing type, or status != pass, raises RV003.
--
-- Apply AFTER schema/schema_v0.sql and step2/roles.sql (same pattern as
-- roles_patch_planner_status.sql / roles_patch_tool_call_audit.sql).
--
-- NOTE: CREATE OR REPLACE FUNCTION does NOT preserve SECURITY DEFINER /
-- SET search_path, so they are re-declared explicitly below.

create or replace function submit_review(p_task uuid, p_ref text, p_reviewer text,
                                         p_verdict text, p_checks jsonb)
returns text language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare t tasks%rowtype; v_creator text; v_new text;
begin
  select * into t from tasks where id = p_task for update;
  if not found then raise exception 'task_not_found' using errcode = 'GR000'; end if;
  if t.state <> 'review' or t.result_ref is distinct from p_ref then
    raise exception 'review_stale' using errcode = 'RV001';  -- ревью строго привязано к хэшу
  end if;
  select created_by into v_creator from artifacts where task_id = p_task and ref = p_ref;
  if v_creator = p_reviewer then raise exception 'self_review' using errcode = 'RV002'; end if;
  if p_verdict = 'approved' then
    if jsonb_typeof(p_checks) <> 'array' then
      raise exception 'checks_failed' using errcode = 'RV003';
    end if;
    -- Strict gate: каждый required check из contract должен иметь ровно
    -- один pass с тем же type. Только длина больше не принимается.
    if exists (
      select 1
      from jsonb_array_elements(coalesce(t.contract->'checks', '[]'::jsonb)) c
      where not exists (
        select 1
        from jsonb_array_elements(p_checks) p
        where p->>'type' = c->>'type'
          and p->>'status' = 'pass'
      )
    ) then
      raise exception 'checks_failed' using errcode = 'RV003';
    end if;
  end if;
  insert into reviews (task_id, artifact_ref, reviewer, verdict, checks)
  values (p_task, p_ref, p_reviewer, p_verdict, p_checks);

  if p_verdict = 'approved' then v_new := 'done';
  elsif p_verdict = 'changes_requested' then
    v_new := case when t.rework + 1 > c_num(t.contract, '{budget,max_rework}', 3)
                  then 'blocked' else 'ready' end;
  else v_new := 'blocked';
  end if;

  update tasks
     set state = v_new,
         rework = rework + case when p_verdict = 'changes_requested' then 1 else 0 end,
         lease_epoch = lease_epoch + case when v_new = 'ready' then 1 else 0 end,
         block_reason = case when v_new = 'blocked' then
                        case when p_verdict = 'rejected' then 'rejected' else 'max_rework' end end,
         updated_at = now()
   where id = p_task;
  perform append_event(p_task, 'review:' || p_ref || ':' || p_reviewer, 'review_submitted',
                       p_reviewer, jsonb_build_object('verdict', p_verdict, 'new_state', v_new));
  if v_new = 'done' then perform promote_ready(); end if;
  return v_new;
end $$;

alter function submit_review(uuid, text, text, text, jsonb) owner to swarm_owner;
alter function submit_review(uuid, text, text, text, jsonb)
  security definer set search_path = public, pg_temp;

grant execute on function submit_review(uuid, text, text, text, jsonb) to swarm_reviewer;

-- roles_patch_tool_call_audit.sql — v0.4 §7: аудит tool calls (shell tools). -- -- ПОЧЕМУ ПАТЧ, А НЕ ПРАВКА schema_v0.sql: -- schema_v0.sql неприкосновенен (ТЗ v0.4 §0 «Неприкосновенно»). -- -- ПОЧЕМУ ФУНКЦИЯ, А НЕ ПРЯМОЙ INSERT В events: -- step2/roles.sql §6 явно закрывает внутренние функции (append_event, assert_lease, -- lock_root, validate_contract, event_hash, c_num) — «журнал нельзя подделать снаружи». -- Прямой insert в events от имени swarm_worker нарушил бы это свойство. Поэтому -- воркер получает одну контролируемую точку входа: она проверяет, что аренда жива -- и принадлежит этому воркеру, и только затем пишет событие от имени swarm_owner. -- -- Применять ПОСЛЕ: schema_v0.sql → step2/roles.sql → step2b/roles_2b.sql. -- Идемпотентен.
-- 1. Разрешить kind='tool_call' (констрейнт расширяется, старые значения сохранены). alter table events drop constraint if exists events_kind_check; alter table events add constraint events_kind_check check (kind in ( 'created', 'dep_added', 'promoted', 'claimed', 'artifact_saved', 'completed', 'review_submitted', 'reclaimed', 'reopened', 'cascade_blocked', 'unblocked', 'tool_call'));
-- 2. Точка входа аудита: только для живого владельца аренды. create or replace function record_tool_call( p_task uuid, p_worker text, p_epoch bigint, p_event_id text, p_payload jsonb) returns boolean language plpgsql as $$ begin -- Аренда жива и принадлежит этому воркеру? Иначе GR-ошибка. perform assert_lease(p_task, p_worker, p_epoch); return append_event(p_task, p_event_id, 'tool_call', p_worker, p_payload); end $$;
-- 3. Права: владелец-не-суперпользователь, исполнение от его имени, доступ только воркеру. alter function record_tool_call(uuid, text, bigint, text, jsonb) owner to swarm_owner; alter function record_tool_call(uuid, text, bigint, text, jsonb) security definer set search_path = public, pg_temp; revoke all on function record_tool_call(uuid, text, bigint, text, jsonb) from public; grant execute on function record_tool_call(uuid, text, bigint, text, jsonb) to swarm_worker;

-- swarm roles 2b v0.2: идентификация воркера.
-- Запуск ПОСЛЕ schema_v0.sql и roles.sql (суперпользователем):
--   psql -v ON_ERROR_STOP=1 -d swarm \
--     -v w1_pw=... -v w2_pw=... \
--     -f step2b/roles_2b.sql
--
-- Задача: закрыть самопровозглашённый worker_id.
-- Проверка активна только для ролей swarm_worker_*; другие роли не затронуты.
--
-- Код ошибки: WK003 worker_identity_mismatch.
--
-- ВАЖНО: schema_v0.sql не меняется. Проверка добавляется через
-- CREATE OR REPLACE. Следующая итерация схемы (v0.3) должна включить
-- её в тела функций.

-- ============================================================
-- 1. Нормализация и проверка идентичности
-- ============================================================

create or replace function normalize_worker_id(p_worker text)
returns text language sql immutable as $$
  select lower(regexp_replace(p_worker, '[-. ]', '_', 'g'))
$$;

create or replace function assert_worker_identity(p_worker text)
returns void language plpgsql as $$
declare v_expected text;
begin
  if session_user::text like 'swarm_worker_%' then
    v_expected := 'swarm_worker_' || normalize_worker_id(p_worker);
    if session_user::text <> v_expected then
      raise exception 'worker_identity_mismatch: session_user=% expected=%',
        session_user, v_expected using errcode = 'WK003';
    end if;
  end if;
end $$;

alter function normalize_worker_id(text) owner to swarm_owner;
alter function assert_worker_identity(text) owner to swarm_owner;
alter function normalize_worker_id(text) security definer set search_path = public, pg_temp;
alter function assert_worker_identity(text) security definer set search_path = public, pg_temp;

revoke all on function normalize_worker_id(text) from public;
revoke all on function assert_worker_identity(text) from public;
-- assert_worker_identity — не выдаём никому; вызывается только из обёрток.

-- ============================================================
-- 2. Переопределение пяти функций воркера с проверкой
-- ============================================================

-- 2.1. register_worker
create or replace function register_worker(p_id text, p_caps jsonb, p_tags text[] default '{}')
returns void language plpgsql as $$
begin
  perform assert_worker_identity(p_id);
  if (p_caps ? 'ram_gb' and jsonb_typeof(p_caps->'ram_gb') <> 'number')
     or (p_caps #> '{models,coder_class}' is not null
         and jsonb_typeof(p_caps #> '{models,coder_class}') <> 'number') then
    raise exception 'worker_invalid' using errcode = 'WK001';
  end if;
  insert into workers (id, capabilities, affinity_tags, last_seen)
  values (p_id, p_caps, coalesce(p_tags, '{}'), now())
  on conflict (id) do update
    set capabilities = excluded.capabilities, affinity_tags = excluded.affinity_tags,
        last_seen = now();
end $$;

-- 2.2. claim_task
create or replace function claim_task(p_worker text, p_lease_sec int default 300)
returns table (out_task_id uuid, out_contract jsonb, out_epoch bigint,
               out_budget bigint, out_spent bigint)
language plpgsql as $$
declare v_id uuid; v_epoch bigint;
begin
  if p_lease_sec <= 0 then
    raise exception 'lease duration must be positive' using errcode = 'CT001';
  end if;
  perform assert_worker_identity(p_worker);
  update workers set last_seen = now() where id = p_worker;
  if not found then raise exception 'worker_unknown' using errcode = 'WK002'; end if;

  select t.id into v_id
  from tasks t join workers w on w.id = p_worker
  where t.state = 'ready'
    and t.spent_tokens < t.budget_cap
    and t.attempts < c_num(t.contract, '{budget,attempts}', 3)
    and c_num(w.capabilities, '{ram_gb}', 0) >= c_num(t.contract, '{needs,min_ram_gb}', 0)
    and c_num(w.capabilities, '{models,coder_class}', 0) >= c_num(t.contract, '{needs,coder_class}', 0)
    and not exists (select 1 from task_deps d join tasks p on p.id = d.dep_id
                    where d.task_id = t.id and p.state <> 'done')
  order by (select count(*) from jsonb_array_elements_text(
              coalesce(t.contract #> '{needs,affinity_tags}', '[]'::jsonb)) x
            where x = any (w.affinity_tags)) desc,
           t.priority desc, t.created_at, t.id
  for update of t skip locked
  limit 1;

  if v_id is null then return; end if;

  update tasks
     set state = 'leased', lease_owner = p_worker, lease_epoch = lease_epoch + 1,
         lease_until = now() + make_interval(secs => p_lease_sec), updated_at = now()
   where id = v_id returning lease_epoch into v_epoch;
  perform append_event(v_id, 'claim:' || v_id || ':' || v_epoch, 'claimed', p_worker,
                       jsonb_build_object('epoch', v_epoch));
  return query select t.id, t.contract, t.lease_epoch, t.budget_cap, t.spent_tokens
               from tasks t where t.id = v_id;
end $$;

-- 2.3. heartbeat
create or replace function heartbeat(p_task uuid, p_worker text, p_epoch bigint,
                                     p_extend_sec int default 300)
returns boolean language plpgsql as $$
begin
  if p_extend_sec <= 0 then
    raise exception 'lease extension must be positive' using errcode = 'CT001';
  end if;
  perform assert_worker_identity(p_worker);
  update tasks set lease_until = now() + make_interval(secs => p_extend_sec),
                   updated_at = now()
   where id = p_task and state = 'leased' and lease_owner = p_worker
     and lease_epoch = p_epoch and lease_until > now();
  if found then update workers set last_seen = now() where id = p_worker; end if;
  return found;
end $$;

-- 2.4. save_artifact
create or replace function save_artifact(p_task uuid, p_worker text, p_epoch bigint,
                                         p_ref text, p_storage text,
                                         p_content_type text default null,
                                         p_size bigint default null)
returns void language plpgsql as $$
begin
  perform assert_worker_identity(p_worker);
  perform assert_lease(p_task, p_worker, p_epoch);
  insert into artifacts (task_id, ref, created_by, lease_epoch, content_type, size_bytes, storage_path)
  values (p_task, p_ref, p_worker, p_epoch, p_content_type, p_size, p_storage)
  on conflict (task_id, ref) do nothing;
  perform append_event(p_task, 'art:' || p_ref, 'artifact_saved', p_worker,
                       jsonb_build_object('ref', p_ref));
end $$;

-- 2.5. complete_task
create or replace function complete_task(p_task uuid, p_worker text, p_epoch bigint,
                                         p_result_ref text, p_tokens bigint default 0)
returns text language plpgsql as $$
declare v_new text; v_spent bigint; v_cap bigint;
begin
  perform assert_worker_identity(p_worker);
  perform assert_lease(p_task, p_worker, p_epoch);
  if p_tokens < 0 then
    raise exception 'tokens must be non-negative' using errcode = 'CT001';
  end if;
  if not exists (select 1 from artifacts where task_id = p_task and ref = p_result_ref) then
    raise exception 'artifact_missing' using errcode = 'AR001';
  end if;
  select spent_tokens + p_tokens, budget_cap into v_spent, v_cap from tasks where id = p_task;
  v_new := case when v_spent > v_cap then 'blocked' else 'review' end;
  update tasks
     set state = v_new, result_ref = p_result_ref, spent_tokens = v_spent,
         lease_owner = null, lease_until = null, updated_at = now(),
         block_reason = case when v_new = 'blocked' then 'budget_exhausted' end
   where id = p_task;
  perform append_event(p_task, 'complete:' || p_epoch, 'completed', p_worker,
                       jsonb_build_object('ref', p_result_ref, 'new_state', v_new, 'tokens', p_tokens));
  return v_new;
end $$;

-- Владелец и режим — для новых тел
alter function register_worker(text, jsonb, text[])          owner to swarm_owner;
alter function claim_task(text, int)                          owner to swarm_owner;
alter function heartbeat(uuid, text, bigint, int)             owner to swarm_owner;
alter function save_artifact(uuid, text, bigint, text, text, text, bigint) owner to swarm_owner;
alter function complete_task(uuid, text, bigint, text, bigint) owner to swarm_owner;

alter function register_worker(text, jsonb, text[])          security definer set search_path = public, pg_temp;
alter function claim_task(text, int)                          security definer set search_path = public, pg_temp;
alter function heartbeat(uuid, text, bigint, int)             security definer set search_path = public, pg_temp;
alter function save_artifact(uuid, text, bigint, text, text, text, bigint) security definer set search_path = public, pg_temp;
alter function complete_task(uuid, text, bigint, text, bigint) security definer set search_path = public, pg_temp;

-- ============================================================
-- 3. Роли для тестов
-- ============================================================
-- Соответствие worker_id → роль:
--   'w1'    → swarm_worker_w1      (без изменений)
--   'w2'    → swarm_worker_w2      (без изменений)
--   'w-1'   → swarm_worker_w_1     (нормализация: дефис → подчёркивание)
--   'GPU-1' → swarm_worker_gpu_1   (нормализация: регистр + дефис)
select 'create role swarm_worker_w1 login password ' || quote_literal(:'w1_pw')
 where not exists (select 1 from pg_roles where rolname = 'swarm_worker_w1') \gexec
select 'create role swarm_worker_w2 login password ' || quote_literal(:'w2_pw')
 where not exists (select 1 from pg_roles where rolname = 'swarm_worker_w2') \gexec
select 'create role swarm_worker_w_1 login password ' || quote_literal(:'w_1_pw')
 where not exists (select 1 from pg_roles where rolname = 'swarm_worker_w_1') \gexec
select 'create role swarm_worker_gpu_1 login password ' || quote_literal(:'gpu_1_pw')
 where not exists (select 1 from pg_roles where rolname = 'swarm_worker_gpu_1') \gexec

alter role swarm_worker_w1    password :'w1_pw';
alter role swarm_worker_w2    password :'w2_pw';
alter role swarm_worker_w_1   password :'w_1_pw';
alter role swarm_worker_gpu_1 password :'gpu_1_pw';

grant swarm_worker to swarm_worker_w1;
grant swarm_worker to swarm_worker_w2;
grant swarm_worker to swarm_worker_w_1;
grant swarm_worker to swarm_worker_gpu_1;
